sys_script_client.script:
function onLoad() {

    // Fields to always show
    var keepFields = [
        'number', 'state', 'assigned_to', 'assignment_group',
        'category_aml', 'sub_category', 'work_notes', 'url', 'scheme_code','sys_updated_on'
    ];

    // Hide all fields except keepFields
    // var allFields = g_form.getFieldNames();
    var allFields = [
        'number', 'state', 'assigned_to', 'assignment_group', 'category_aml', 'sub_category', 'work_notes', 'url', 'scheme_code', 'member_account_type_1_ee', 'identification_passportno_auth_pers_1', 'identification_hkid_card_auth_pers_1',
        'employer_account_type', 'er_id', 'surname_in_english_auth_pers_1', 'given_name_in_english_auth_pers_1',
        'client_date_of_birth', 'mstranno_count', 'tranamt01_total', 'extraction_date', 'hit_rule_no',
        'sub_activity_code', 'transaction_date', 'contribution_mstranno_count', 'contribution_tranamt01_total',
        'withdrawal_mstranno_count', 'withdrawal_tranamt01_total', 'employer_information', 'relincom_total',
        'contribution_end_date', 'contribution_start_date', 'contribution_frequency', 'relincom_tranamt_100', 'active'
    ];

    allFields.forEach(function(field) {
        if (keepFields.indexOf(field) === -1 && g_form.getControl(field)) {
            g_form.setDisplay(field, false);
        }
    });

    var category = g_form.getValue('category_aml');
    var subcat = g_form.getValue('sub_category');

    // Show extra fields based on category/subcat
    if ((category == 'new_enrollment' || category == 'periodic_review_query') && subcat == 'ee') {
        g_form.setDisplay('member_account_type_1_ee', true);
        g_form.setMandatory('member_account_type_1_ee', true);
        g_form.setDisplay('identification_passportno_auth_pers_1', true);
        g_form.setDisplay('identification_hkid_card_auth_pers_1', true);
    }
    if ((category == 'new_enrollment' || category == 'periodic_review_query') && subcat == 'er') {
        g_form.setDisplay('employer_account_type', true);
        g_form.setMandatory('employer_account_type', true);
        g_form.setDisplay('er_id', true);
        g_form.setMandatory('er_id', true);
    }
    if (category == 'rule_1' || category == 'rule_2' || category == 'rule_4') {
        g_form.setDisplay('identification_passportno_auth_pers_1', true);
        g_form.setDisplay('identification_hkid_card_auth_pers_1', true);
        g_form.setDisplay('surname_in_english_auth_pers_1', true);
        g_form.setDisplay('given_name_in_english_auth_pers_1', true);
        g_form.setDisplay('client_date_of_birth', true);
        g_form.setDisplay('mstranno_count', true);
        g_form.setDisplay('tranamt01_total', true);
        g_form.setDisplay('extraction_date', true);
        g_form.setDisplay('hit_rule_no', true);
    }
    if (category == 'rule_3') {
        g_form.setDisplay('identification_passportno_auth_pers_1', true);
        g_form.setDisplay('identification_hkid_card_auth_pers_1', true);
        g_form.setDisplay('surname_in_english_auth_pers_1', true);
        g_form.setDisplay('given_name_in_english_auth_pers_1', true);
        g_form.setDisplay('client_date_of_birth', true);
        g_form.setDisplay('mstranno_count', true);
        g_form.setDisplay('tranamt01_total', true);
        g_form.setDisplay('extraction_date', true);
        g_form.setDisplay('hit_rule_no', true);
        g_form.setDisplay('sub_activity_code', true);
        g_form.setDisplay('transaction_date', true);
    }
    if (category == 'rule_5') {
        g_form.setDisplay('identification_passportno_auth_pers_1', true);
        g_form.setDisplay('identification_hkid_card_auth_pers_1', true);
        g_form.setDisplay('surname_in_english_auth_pers_1', true);
        g_form.setDisplay('given_name_in_english_auth_pers_1', true);
        g_form.setDisplay('client_date_of_birth', true);
        g_form.setDisplay('contribution_mstranno_count', true);
        g_form.setDisplay('contribution_tranamt01_total', true);
        g_form.setDisplay('extraction_date', true);
        g_form.setDisplay('hit_rule_no', true);
        g_form.setDisplay('withdrawal_mstranno_count', true);
        g_form.setDisplay('withdrawal_tranamt01_total', true);
    }
    if (category == 'rule_11') {
        g_form.setDisplay('identification_passportno_auth_pers_1', true);
        g_form.setDisplay('identification_hkid_card_auth_pers_1', true);
        g_form.setDisplay('surname_in_english_auth_pers_1', true);
        g_form.setDisplay('given_name_in_english_auth_pers_1', true);
        g_form.setDisplay('client_date_of_birth', true);
        g_form.setDisplay('employer_information', true);
        g_form.setDisplay('relincom_total', true);
        g_form.setDisplay('tranamt01_total', true);
        g_form.setDisplay('extraction_date', true);
        g_form.setDisplay('hit_rule_no', true);
        g_form.setDisplay('contribution_end_date', true);
        g_form.setDisplay('contribution_start_date', true);
        g_form.setDisplay('contribution_frequency', true);
        g_form.setDisplay('relincom_tranamt_100', true);
    }

}
